def tekst(con, mid, imya, pole):
    r = con.execute(f"select name, {pole} from metric where id=?", (mid,)).fetchone()
    if not r or r[0] != imya:
        return None, False
    return r[1], True


def primenit(con):
    otchet = []
    for mid, imya, pole, bylo, stalo, punkt in TSELIKOM:
        t, est = tekst(con, mid, imya, pole)
        if not est:
            otchet.append(f"⛔ {mid}: ждали «{imya}», в Базе другое — не менял"); continue
        if (t or None) == (stalo or None):
            continue
        if (t or None) != (bylo or None):
            otchet.append(f"⛔ {mid}.{pole} «{imya}»: в поле не то, что ждали, не менял"); continue
        con.execute(f"update metric set {pole}=? where id=?", (stalo, mid))
        otchet.append(f"{punkt} {mid}.{pole} «{imya}»")
    for mid, imya, pole, bylo, stalo, punkt in PRAVKI:
        t, est = tekst(con, mid, imya, pole)
        if not est:
            otchet.append(f"⛔ {mid}: ждали «{imya}», в Базе другое — не менял"); continue
        t = t or ""
        if stalo in t:
            continue
        if bylo not in t:
            otchet.append(f"⛔ {mid}.{pole} «{imya}»: исходный текст не найден, не менял"); continue
        con.execute(f"update metric set {pole}=? where id=?", (t.replace(bylo, stalo, 1), mid))
        otchet.append(f"{punkt} {mid}.{pole} «{imya}»")
    for mid, n, bylo, stalo, punkt in VOPROSY:
        r = con.execute("select id, text from question where metric_id=? and priority=?", (mid, n)).fetchone()
        if not r:
            otchet.append(f"⛔ вопрос {n} у {mid} не найден"); continue
        if r[1] == stalo:
            continue
        if r[1] != bylo:
            otchet.append(f"⛔ вопрос {n} у {mid}: текст не тот, не менял"); continue
        con.execute("update question set text=? where id=?", (stalo, r[0]))
        otchet.append(f"{punkt} вопрос {n} у {mid}")
    return otchet or ["всё уже внесено"]


def proverit(con):
    pr = []
    uzly = {r[0] for r in con.execute("select node_id from metric_artifact where node_id is not null")}
    uzly |= {"spravochnik/" + r[0] for r in con.execute("select slug from metric")}
    for mid, imya, pole, bylo, stalo, punkt in TSELIKOM:
        t, est = tekst(con, mid, imya, pole)
        if not est or (t or None) != (stalo or None):
            pr.append(f"⛔ {punkt} {mid}.{pole} «{imya}»: не новый текст")
    for mid, imya, pole, bylo, stalo, punkt in PRAVKI:
        t, est = tekst(con, mid, imya, pole)
        if not est or stalo not in (t or ""):
            pr.append(f"⛔ {punkt} {mid}.{pole} «{imya}»: новой правки нет")
        elif bylo != stalo[:len(bylo)] and bylo in (t or ""):
            pr.append(f"⛔ {punkt} {mid}.{pole} «{imya}»: старый текст остался")
        for adres in re.findall(r"\[\[[^\]→]+→([^\]]+)\]\]", stalo):
            if adres not in uzly:
                pr.append(f"⛔ {punkt} {mid}.{pole}: ссылка в никуда {adres}")
    for mid, n, bylo, stalo, punkt in VOPROSY:
        r = con.execute("select text from question where metric_id=? and priority=?", (mid, n)).fetchone()
        if not r or r[0] != stalo:
            pr.append(f"⛔ {punkt} вопрос {n} у {mid}: не новый текст")
    return pr


def main():
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    put = pathlib.Path(sys.argv[1]).resolve()
    if not put.exists():
        sys.exit(f"✖ базы нет: {put}")
    con = sqlite3.connect(put)
    con.execute("pragma foreign_keys=on")
    if "--check" not in sys.argv:
        kopiya = put.with_name(f"{put.stem}.before_020_{datetime.datetime.now():%Y%m%d_%H%M%S}{put.suffix}")
        shutil.copy2(put, kopiya)
        print(f"бэкап: {kopiya.name}")
        for s in primenit(con):
            print("  " + s)
        con.commit()
    pr = proverit(con)
    if pr:
        print(f"\nпретензий: {len(pr)}")
        for p in pr:
            print(" ", p)
        sys.exit(1)
    print("проверка: чисто")


if __name__ == "__main__":
    main()
